def normalized_arxiv(value):
    match = re.fullmatch(r"(?:(?:https?://(?:export\.)?arxiv\.org/abs/)|arxiv:\s*)?"
                         r"(\d{4}\.\d{4,5}|[a-z-]+(?:\.[a-z]{2})?/\d{7})(?:v\d+)?", str(value or "").strip(), re.I)
    return match[1].casefold() if match else ""


def arxiv_observation(arxiv, cassette, attempts):
    exact = "10.48550/arxiv." + arxiv
    url = "https://api.datacite.org/dois/" + quote(exact, safe="/")
    receipt = cassette.get(url, {})
    attempts.append(dict(provider="DataCite (arXiv DOI)", url=url,
                         status=receipt.get("status") or "unavailable", queried_at=receipt.get("queried_at")))
    attributes = ((receipt.get("body") or {}).get("data") or {}).get("attributes") or {}
    if receipt.get("status") == 404:
        return "not_found", {}, set()
    if receipt.get("status") != 200 or normalize_doi(attributes.get("doi")) != exact:
        return "unavailable", {}, set()
    titles = attributes.get("titles") or []
    title = titles[0].get("title") if titles and isinstance(titles[0], dict) else None
    relations = {normalize_doi(row.get("relatedIdentifier")) for row in (attributes.get("relatedIdentifiers") or [])[:24]
                 if isinstance(row, dict) and row.get("relatedIdentifierType") == "DOI"
                 and row.get("relationType") in {"IsVersionOf", "HasVersion", "IsIdenticalTo", "IsPreprintOf", "HasPreprint"}}
    return "matched", dict(doi=exact, title=title, provider="DataCite (arXiv DOI)", record_id=arxiv,
                           url="https://arxiv.org/abs/" + arxiv, queried_at=receipt.get("queried_at")), relations


def crossref_related_preprint(doi, arxiv, cassette):
    receipt = cassette.get("https://api.crossref.org/works/" + quote(doi, safe="/"), {})
    msg = (receipt.get("body") or {}).get("message") or {}
    if normalize_doi(msg.get("DOI")) != doi:
        return False
    relation = msg.get("relation") or {}
    if not isinstance(relation, dict):
        return False
    ids = [row.get("id") for key, rows in relation.items()
           if key in {"has-preprint", "is-preprint-of", "is-version-of", "has-version"} and isinstance(rows, list)
           for row in rows[:24] if isinstance(row, dict)]
    return any(normalized_arxiv(value) == arxiv or normalize_doi(value) == "10.48550/arxiv." + arxiv for value in ids)


